  ('prod-wallet-01', 'Premium Leather Wallet', 1450, 1850, 'cat-mens-accessories', 'Handcrafted top-grain cowhide leather wallet with RFID blocking technology, 8 card slots, dual cash compartments, and an ultra-slim bifold profile.', 'https://images.unsplash.com/photo-1627123424574-724758594e93?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1627123424574-724758594e93?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=800&q=80"]', 24, 1, 4.9, 42, '["Material: 100% Genuine Cowhide Leather","RFID Protection Shielding","Dimensions: 11cm x 9cm x 1.5cm","Warranty: 1 Year Craftsmanship Guarantee"]', 'prod-wallet-01', 'active', '2026-03-01T10:00:00.000Z', CURRENT_TIMESTAMP),
  ('prod-bracelet-02', 'Stainless Steel Bracelet', 850, 1100, 'cat-mens-accessories', 'Polished 316L medical-grade stainless steel curb chain bracelet with heavy-duty interlocking clasp. Anti-tarnish, waterproof, and hypoallergenic.', 'https://images.unsplash.com/photo-1611591475862-23c51ef67ee6?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1611591475862-23c51ef67ee6?auto=format&fit=crop&w=800&q=80"]', 19, 0, 4.7, 28, '["Material: 316L Surgical Grade Steel","Length: 21 cm (Adjustable links)","Waterproof & Sweat-proof","Color: Obsidian Silver & Gunmetal"]', 'prod-bracelet-02', 'active', '2026-03-02T11:00:00.000Z', CURRENT_TIMESTAMP),
  ('prod-watch-03', 'Luxury Quartz Watch', 3200, 4200, 'cat-mens-accessories', 'Sophisticated analog timepiece with sapphire crystal glass, Japanese Miyota quartz movement, date display, and genuine leather strap.', 'https://images.unsplash.com/photo-1524805444758-089113d48a6d?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1524805444758-089113d48a6d?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1542496658-e33a6d0d50f6?auto=format&fit=crop&w=800&q=80"]', 7, 1, 4.9, 65, '["Movement: Japanese Quartz","Glass: Scratch-resistant Sapphire","Water Resistance: 50M (5 ATM)","Strap: Genuine Italian Leather"]', 'prod-watch-03', 'active', '2026-03-03T12:00:00.000Z', CURRENT_TIMESTAMP),
