  ('prod-cap-04b', 'Mens Casual Cap', 650, 850, 'cat-mens-accessories', 'Premium breathable cotton curved-brim baseball cap featuring an adjustable brass metal closure buckle and embroidered minimal front accent.', 'https://images.unsplash.com/photo-1588850561407-ed78c282e89b?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1588850561407-ed78c282e89b?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1575428652377-a2d80e2277fc?auto=format&fit=crop&w=800&q=80"]', 25, 0, 4.8, 19, '["Material: 100% Breathable Brushed Cotton","Strap: Antique Brass Metal Sliding Buckle","Size: Free Size (56-60 cm circumference)","Visor: Pre-curved UV Guard Stitched Brim"]', 'prod-cap-04b', 'active', '2026-03-04T14:00:00.000Z', CURRENT_TIMESTAMP),
  ('prod-sunglasses-04c', 'Polarized Sunglasses for Men', 1350, 1750, 'cat-mens-accessories', 'Classic square frame UV400 polarized sunglasses featuring anti-glare TAC lenses, lightweight aluminum-magnesium temples, and spring hinges for maximum comfort.', 'https://images.unsplash.com/photo-1511499767150-a48a237f0083?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1511499767150-a48a237f0083?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1572635196237-14b3f281503f?auto=format&fit=crop&w=800&q=80"]', 16, 1, 4.8, 37, '["Lenses: TAC Polarized UV400 Protection","Frame: Matte Black Alloy & Acetate","Includes: Hard protective case & microfiber cleaning cloth","Weight: Ultra-light 28 grams"]', 'prod-sunglasses-04c', 'active', '2026-03-04T15:00:00.000Z', CURRENT_TIMESTAMP),

-- Gadgets & Electronics
  ('prod-tws-05', 'ANC TWS Earbuds', 2100, 2800, 'cat-gadgets-electronics', 'Active Noise Cancelling true wireless earbuds featuring 13mm dynamic drivers, low-latency gaming mode, 32-hour total playtime, and quad-mic ENC for crystal-clear calling.', 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1590658268037-6bf12165a8df?auto=format&fit=crop&w=800&q=80"]', 22, 1, 4.9, 88, '["Noise Cancellation: Up to 35dB Active Hybrid ANC","Bluetooth: 5.3 Quick Connect","Battery: 7 hrs buds + 25 hrs case","IPX5 Water Resistant"]', 'prod-tws-05', 'active', '2026-03-05T14:00:00.000Z', CURRENT_TIMESTAMP),
  ('prod-powerbank-06', 'Heavy Duty Power Bank 20000mAh', 2850, 3400, 'cat-gadgets-electronics', 'High-density 20,000mAh lithium-polymer power bank supporting 22.5W Super Charge and 20W Power Delivery. Features an intelligent LED battery percentage readout.', 'https://images.unsplash.com/photo-1609592426868-8097d74db1a7?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1609592426868-8097d74db1a7?auto=format&fit=crop&w=800&q=80"]', 11, 1, 4.8, 54, '["Capacity: 20,000mAh / 74Wh","Ports: 2x USB-A QC 3.0, 1x USB-C Bi-directional PD","Digital LED Battery Level Display","Multi-layer Overcharge Protection"]', 'prod-powerbank-06', 'active', '2026-03-06T15:00:00.000Z', CURRENT_TIMESTAMP),
  ('prod-speaker-07', 'Portable Bluetooth Speaker', 1950, 2450, 'cat-gadgets-electronics', 'Compact rugged cylindrical outdoor speaker delivering 360-degree room-filling acoustic sound with deep bass radiators and vibrant RGB pulsing rhythm lights.', 'https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?auto=format&fit=crop&w=800&q=80"]', 8, 0, 4.7, 39, '["Audio Output: 16W Dual Drivers with Bass Radiator","Playtime: Up to 12 Hours","Water Resistance: IPX7 Submersible","RGB Audio Sync Lighting Modes"]', 'prod-speaker-07', 'active', '2026-03-07T16:00:00.000Z', CURRENT_TIMESTAMP),
  ('prod-charger-08', '65W Fast Phone Charger', 1200, 1600, 'cat-gadgets-electronics', 'Next-gen GaN (Gallium Nitride) triple-port fast wall charger. Powers laptops, MacBooks, iPhones, Samsung flagships, and tablets simultaneously in a pocket-sized form.', 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1583863788434-e58a36330cf0?auto=format&fit=crop&w=800&q=80"]', 27, 0, 4.9, 71, '["Technology: GaN III Fast Power Delivery","Output: 65W Max (2x USB-C + 1x USB-A)","Compatibility: PD 3.0, QC 4+, PPS","Universal Bangladeshi 2-pin Pin Plug"]', 'prod-charger-08', 'active', '2026-03-08T17:00:00.000Z', CURRENT_TIMESTAMP),
  ('prod-headphones-09', 'Over-Ear Headphones', 3500, 4500, 'cat-gadgets-electronics', 'Studio-grade wireless over-ear headphones with plush memory foam earcups, 40mm titanium drivers, environmental noise cancelling mic, and 50-hour ultra-long battery life.', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=800&q=80"]', 6, 1, 4.9, 93, '["Drivers: 40mm Titanium diaphragm","Battery: 50 Hours (10 min charge = 5 hours)","Foldable Ergonomic Swivel Design","3.5mm Aux Wired & Bluetooth 5.3"]', 'prod-headphones-09', 'active', '2026-03-09T18:00:00.000Z', CURRENT_TIMESTAMP),
  ('prod-mouse-09b', 'Ergonomic Wireless Mouse', 950, 1350, 'cat-gadgets-electronics', 'Silent-click dual-mode (Bluetooth 5.2 + 2.4GHz USB Dongle) ergonomic rechargeable mouse with 2400 DPI precision tracking and contoured thumb rest.', 'https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?auto=format&fit=crop&w=800&q=80"]', 20, 0, 4.8, 41, '["Connectivity: Dual Mode Bluetooth 5.2 + 2.4G Nano USB","DPI Levels: 800 - 1200 - 1600 - 2400 DPI","Battery: USB-C 500mAh Rechargeable (60 Days standby)","Silent Whisper Clicks: 90% Noise Reduction"]', 'prod-mouse-09b', 'active', '2026-03-09T19:00:00.000Z', CURRENT_TIMESTAMP),

