  ('prod-giftbox-10', 'Customized Wooden Gift Box', 1800, 2200, 'cat-gift-items', 'Artisan carved pine wood keepsake box with brass vintage latch, personalized laser engraving plate, velvet interior lining, and satin ribbon presentation.', 'https://images.unsplash.com/photo-1549465220-1a8b9238cd48?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1549465220-1a8b9238cd48?auto=format&fit=crop&w=800&q=80"]', 15, 1, 4.9, 47, '["Wood: Sustainable Solid Pine with Honey Varnish","Customizable Name/Date Plate","Lining: Rich Royal Maroon Velvet","Dimensions: 22cm x 15cm x 8cm"]', 'prod-giftbox-10', 'active', '2026-03-10T19:00:00.000Z', CURRENT_TIMESTAMP),
