  ('prod-penjournal-12', 'Luxury Pen & Journal Combo', 1150, 1450, 'cat-gift-items', 'Executive gift pairing containing an engraved 0.5mm tungsten ballpoint roller pen in matte black alongside a 240-page bleed-proof faux leather bound diary.', 'https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=800&q=80"]', 20, 0, 4.8, 34, '["Pen: Heavyweight Brass Body with Refillable Ink","Journal: 120 GSM Acid-free Cream Paper","Features: Ribbon Bookmark, Pen Loop & Expandable Pocket","Packaged in a debossed magnetic gift box"]', 'prod-penjournal-12', 'active', '2026-03-12T21:00:00.000Z', CURRENT_TIMESTAMP),
